import type * as Common from '../../core/common/common.js';
import * as i18n from '../../core/i18n/i18n.js';
import * as Trace from '../../models/trace/trace.js';
import * as PerfUI from '../../ui/legacy/components/perf_ui/perf_ui.js';
import * as UI from '../../ui/legacy/legacy.js';

import {buildGroupStyle, buildTrackHeader, drawWhiskers, WHISKER_STROKE_COLOR} from './AppenderUtils.js';
import {
  type CompatibilityTracksAppender,
  type DrawOverride,
  type PopoverInfo,
  type TrackAppender,
  type TrackAppenderName,
  VisualLoggingTrackName,
} from './CompatibilityTracksAppender.js';
import * as Components from './components/components.js';

const UIStrings = {
  /**
   * @description Header for the interactions track in the timeline flame chart of the Performance panel.
   */
  interactions: 'Interactions',
} as const;

const str_ = i18n.i18n.registerUIStrings('panels/timeline/InteractionsTrackAppender.ts', UIStrings);
const i18nString = i18n.i18n.getLocalizedString.bind(undefined, str_);

export class InteractionsTrackAppender implements TrackAppender {
  readonly appenderName: TrackAppenderName = 'Interactions';

  #colorGenerator: Common.Color.Generator;
  #compatibilityBuilder: CompatibilityTracksAppender;
  #parsedTrace: Readonly<Trace.TraceModel.ParsedTrace>;

  constructor(
      compatibilityBuilder: CompatibilityTracksAppender, parsedTrace: Trace.TraceModel.ParsedTrace,
      colorGenerator: Common.Color.Generator) {
    this.#compatibilityBuilder = compatibilityBuilder;
    this.#colorGenerator = colorGenerator;
    this.#parsedTrace = parsedTrace;
  }

  /**
   * Appends into the flame chart data the data corresponding to the
   * interactions track.
   * @param trackStartLevel the horizontal level of the flame chart events where
   * the track's events will start being appended.
   * @param expanded whether the track should be rendered expanded.
   * @returns the first available level to append more data after having
   * appended the track's events.
   */
  appendTrackAtLevel(trackStartLevel: number, expanded?: boolean): number {
    if (this.#parsedTrace.data.UserInteractions.interactionEvents.length === 0) {
      return trackStartLevel;
    }
    this.#appendTrackHeaderAtLevel(trackStartLevel, expanded);
    return this.#appendInteractionsAtLevel(trackStartLevel);
  }

  /**
   * Adds into the flame chart data the header corresponding to the
   * interactions track. A header is added in the shape of a group in the
   * flame chart data. A group has a predefined style and a reference
   * to the definition of the legacy track (which should be removed
   * in the future).
   * @param currentLevel the flame chart level at which the header is
   * appended.
   */
  #appendTrackHeaderAtLevel(currentLevel: number, expanded?: boolean): void {
    const trackIsCollapsible = this.#parsedTrace.data.UserInteractions.interactionEvents.length > 0;
    const style = buildGroupStyle({
      collapsible: trackIsCollapsible ? PerfUI.FlameChart.GroupCollapsibleState.IF_MULTI_ROW :
                                        PerfUI.FlameChart.GroupCollapsibleState.NEVER,
      useDecoratorsForOverview: true,
    });
    const group = buildTrackHeader(
        VisualLoggingTrackName.INTERACTIONS, currentLevel, i18nString(UIStrings.interactions), style,
        /* selectable= */ true, expanded);
    this.#compatibilityBuilder.registerTrackForGroup(group, this);
  }

  /**
   * Adds into the flame chart data the trace events dispatched by the
   * performance.measure API. These events are taken from the UserInteractions
   * handler.
   * @param currentLevel the flame chart level from which interactions will
   * be appended.
   * @returns the next level after the last occupied by the appended
   * interactions (the first available level to append more data).
   */
  #appendInteractionsAtLevel(trackStartLevel: number): number {
    const {interactionEventsWithNoNesting, interactionsOverThreshold} = this.#parsedTrace.data.UserInteractions;

    const addCandyStripeToLongInteraction =
        (event: Trace.Types.Events.SyntheticInteractionPair, index: number): void => {
          // Each interaction that we drew that is over the INP threshold needs to be
          // candy-striped.
          const overThreshold = interactionsOverThreshold.has(event);
          if (!overThreshold) {
            return;
          }
          if (index !== undefined) {
            this.#addCandyStripeAndWarningForLongInteraction(event, index);
          }
        };
    // Render all top level interactions (see UserInteractionsHandler for an explanation on the nesting) onto the track.
    const newLevel = this.#compatibilityBuilder.appendEventsAtLevel(
        interactionEventsWithNoNesting, trackStartLevel, this, addCandyStripeToLongInteraction);

    return newLevel;
  }

  #addCandyStripeAndWarningForLongInteraction(entry: Trace.Types.Events.SyntheticInteractionPair, eventIndex: number):
      void {
    const decorationsForEvent =
        this.#compatibilityBuilder.getFlameChartTimelineData().entryDecorations[eventIndex] || [];
    decorationsForEvent.push(
        {
          type: PerfUI.FlameChart.FlameChartDecorationType.CANDY,
          // Where the striping starts is hard. The problem is the whole interaction, isolating the part of it *responsible* for
          // making the interaction 200ms is hard and our decoration won't do it perfectly. To simplify we just flag all the overage.
          // AKA the first 200ms of the interaction aren't flagged. A downside is we often flag a lot of render delay.
          // It'd be fair to shift the candystriping segment earlier in the interaction... Let's see what the feedback is like.
          startAtTime: Trace.Handlers.ModelHandlers.UserInteractions.LONG_INTERACTION_THRESHOLD,
        },
        {
          type: PerfUI.FlameChart.FlameChartDecorationType.WARNING_TRIANGLE,
          customEndTime: entry.processingEnd,
        });
    this.#compatibilityBuilder.getFlameChartTimelineData().entryDecorations[eventIndex] = decorationsForEvent;
  }

  /*
    ------------------------------------------------------------------------------------
     The following methods  are invoked by the flame chart renderer to query features about
     events on rendering.
    ------------------------------------------------------------------------------------
  */

  /**
   * Gets the color an event added by this appender should be rendered with.
   */
  colorForEvent(event: Trace.Types.Events.Event): string {
    let idForColorGeneration = Trace.Name.forEntry(event, this.#parsedTrace);
    if (Trace.Types.Events.isSyntheticInteraction(event)) {
      // Append the ID so that we vary the colours, ensuring that two events of
      // the same type are coloured differently.
      idForColorGeneration += event.interactionId;
    }
    return this.#colorGenerator.colorForID(idForColorGeneration);
  }

  getDrawOverride(event: Trace.Types.Events.Event): DrawOverride|undefined {
    if (!Trace.Types.Events.isSyntheticInteraction(event)) {
      return undefined;
    }

    return (context, x, y, width, height, timeToPosition, transformColor): PerfUI.FlameChart.PositionOverride => {
      /**
       * An interaction is drawn with whiskers as so:
       * |----------[=======]-------------|
       * => The left whisker is the event's start time (event.ts)
       * => The box start is the event's processingStart time
       * => The box end is the event's processingEnd time
       * => The right whisker is the event's end time (event.ts + event.dur)
       */
      let boxStartX = timeToPosition(Trace.Helpers.Timing.microToMilli(event.processingStart));
      const boxEndX = timeToPosition(Trace.Helpers.Timing.microToMilli(event.processingEnd));

      // If the entry has no processing duration, ensure the box is 1px wide so at least it is visible.
      if (event.processingEnd - event.processingStart === 0) {
        boxStartX -= 1;
      }
      const boxWidth = Math.max(boxEndX - boxStartX, 1);

      context.save();

      // Draw whiskers before the box so the box covers any overlap when input or presentation delay is 0.
      drawWhiskers(context, x, boxStartX, boxEndX, x + width, y, height, transformColor(WHISKER_STROKE_COLOR));

      context.fillStyle = transformColor(this.colorForEvent(event));
      context.fillRect(boxStartX, y, boxWidth, height - 1);

      const entryTitle = Trace.Name.forEntry(event, this.#parsedTrace);
      if (entryTitle) {
        // Fallback to x=0 if the box starts off-screen to the left so the user can still see the event's title.
        const textStartX = boxStartX > 0 ? boxStartX : 0;
        // These numbers are duplicated from FlameChart.ts.
        const textPadding = 5;
        const textBaseline = 5;
        const visibleBoxWidth = boxEndX - textStartX;
        const maxTextWidth = visibleBoxWidth - 2 * textPadding;
        const trimmedTitle =
            maxTextWidth > 10 ? UI.UIUtils.trimTextMiddle(context, entryTitle, maxTextWidth) : entryTitle;
        const textWidth = UI.UIUtils.measureTextWidth(context, trimmedTitle);

        // Only draw the text if it can fit in the amount of box that is visible.
        if (textWidth <= visibleBoxWidth - 2 * textPadding) {
          context.fillStyle = transformColor('#333');
          context.fillText(trimmedTitle, textStartX + textPadding, y + height - textBaseline);
        }
      }

      context.restore();

      return {x, width: Math.max(width, 1)};
    };
  }

  setPopoverInfo(event: Trace.Types.Events.Event, info: PopoverInfo): void {
    if (Trace.Types.Events.isSyntheticInteraction(event)) {
      info.additionalElements.push(Components.InteractionBreakdown.InteractionBreakdown.createWidgetElement(event));
    }
  }
}
